// Acepta tanto {args:{...}} (como manda Retell) como el cuerpo plano.
const b = $input.first().json.body || $input.first().json || {};
const a = b.args || b;
const t = (x) => String(x ?? '').trim();
return [{ json: {
  operacion: (t(a.operacion).toLowerCase().startsWith('alq') ? 'alquiler' : 'compra'),
  zona: t(a.zona), tipo: t(a.tipo),
  precio_max: t(a.precio_max), habitaciones_min: t(a.habitaciones_min),
}}];

// Busca en el inventario de la web por caracteristicas y devuelve las mejores
// coincidencias. La tabla es pequena (unos 180 inmuebles), asi que se traen
// todos los de la operacion y se puntuan aqui: sale mas simple y mas flexible
// que intentar filtrar por rangos en columnas de texto.
const a = $('Lo que pide el cliente').first().json;
const filas = $input.all().map((x) => x.json).filter((f) => f && f.Referencia && f.Referencia !== 'TEST-1');

const num = (t) => { const m = String(t ?? '').replace(/\./g, '').match(/\d+/); return m ? Number(m[0]) : null; };
const norm = (t) => String(t ?? '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '');   // sin acentos, para comparar

// Todo lo que no es vivienda. Si el cliente no pide expresamente un garaje o un
// local, ofrecerselo queda mal: un comercial no lo haria.
const NO_VIVIENDA = ['garaje','trastero','terreno','solar','local','nave','oficina','negocio',
                     'almacen','pabellon','suelo','edificio','singular','amarre','hotel'];
// Sin tipo no se puede saber que es, asi que tampoco se ofrece a ciegas.
const esVivienda = (tipo) => !!String(tipo ?? '').trim() && !NO_VIVIENDA.some((p) => norm(tipo).includes(p));

const pedidas = {
  zona: norm(a.zona), tipo: norm(a.tipo),
  precioMax: num(a.precio_max), habMin: num(a.habitaciones_min),
};

const candidatos = [];
for (const f of filas) {
  const precio = num(f.PrecioTexto);
  const hab = num(f.Habitaciones);

  // Descartes duros: si pide un tope de precio, un minimo de habitaciones o un
  // tipo concreto, no tiene sentido ofrecerle algo que no lo cumple.
  if (pedidas.precioMax && precio && precio > pedidas.precioMax) continue;
  if (pedidas.habMin && hab !== null && hab < pedidas.habMin) continue;
  if (pedidas.tipo && !norm(f.Tipo).includes(pedidas.tipo)) continue;
  // Sin tipo pedido, solo viviendas.
  if (!pedidas.tipo && !esVivienda(f.Tipo)) continue;

  let puntos = 0;
  if (pedidas.zona && norm(f.Zona).includes(pedidas.zona)) puntos += 3;
  if (pedidas.habMin && hab === pedidas.habMin) puntos += 1;
  if (pedidas.precioMax && precio) puntos += 1;   // cabe en presupuesto
  candidatos.push({ f, puntos, precio: precio ?? Number.MAX_SAFE_INTEGER });
}

// Mejor puntuacion primero y, a igualdad, mas barato.
candidatos.sort((x, y) => y.puntos - x.puntos || x.precio - y.precio);
const top = candidatos.slice(0, 3);

if (!top.length) {
  return [{ json: { encontrados: 0, texto:
    'No hay ningun inmueble publicado que encaje con esas caracteristicas. ' +
    'Ofrecete a tomar nota de lo que busca para que un compañero le avise cuando entre algo.' }}];
}

const texto = top.map((c, i) => {
  const f = c.f;
  const d = [f.Tipo, f.Zona ? `en ${f.Zona}` : null, f.PrecioTexto, f.Superficie,
             // Las filas antiguas guardaban "4 Hab."; se queda solo el numero.
             (num(f.Habitaciones) ? `${num(f.Habitaciones)} hab` : null)]
    .filter(Boolean).join(', ');
  return `${i + 1}. Referencia ${f.Referencia}: ${d}. Ficha: ${f.Url}`;
}).join('\n');

return [{ json: { encontrados: top.length, texto:
  `Estos son los que mas se acercan:\n${texto}` }}];
